async function lihat(){try{const e=await(await fetch("/api/template",{method:"GET"})).json();document.getElementById("templateModalLabel").innerHTML="Lihat Template "+e.data.nama;const a=document.getElementById("list-group");a.innerHTML="",e.data&&e.data.template&&listTemplate(e.data.template),document.getElementById("templateModal").showModal()}catch(t){console.error("Gagal load template:",t),document.getElementById("list-group").innerHTML=""}}function listTemplate(t){const e=document.getElementById("list-group");e.innerHTML="";let a="";t.forEach(n=>{a+=`
        <li id="tpl-${n.id}" 
            class="flex justify-between items-center bg-base-100 p-3 rounded-lg border border-base-200 hover:border-primary cursor-pointer transition-all shadow-sm group" 
            onclick="preview('${n.id}')">
            
            <div class="flex-1">
                <div class="font-bold text-base-content">${n.kegiatan}</div>
                <div class="text-sm text-base-content/70">${n.satuan}</div>
            </div>
            
            <button type="button" class="btn btn-error btn-sm btn-square opacity-80 hover:opacity-100 transition-opacity" 
                onclick="hapus(event, '${n.id}')" title="Hapus Template">
                <i class="fa-regular fa-trash-can text-white"></i>
            </button>
        </li>`}),e.innerHTML=a}async function hapus(t,e){t.stopPropagation();try{if((await fetch(`/api/template?id=${e}`,{method:"DELETE"})).ok){Swal.fire({icon:"success",title:"Berhasil dihapus",showConfirmButton:!1,timer:1500});const n=document.getElementById(`tpl-${e}`);n&&n.remove()}}catch(a){console.error("Gagal menghapus:",a)}}async function simpan(){const t=parseInt(document.getElementById("InputCompletion").value),e=parseInt(document.getElementById("InputVolume").value),a=document.getElementById("InputActivities").value,n=document.getElementById("Unit").value;let i={kegiatan:a,satuan:n};if(isNaN(t)||(i.waktu=t),isNaN(e)||(i.volume=e),a!=="")try{const o=await fetch("/api/template",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(i)}),s=await o.json();o.ok?Swal.fire({icon:"success",title:s.data?s.data.title:"Berhasil Disimpan"}):Swal.fire({icon:"error",title:o.statusText||"Gagal menyimpan"})}catch(o){console.error("Gagal menyimpan:",o),Swal.fire({icon:"error",title:"Terjadi kesalahan koneksi"})}else Swal.fire({icon:"warning",title:"Oops...",text:"Kegiatan kerja tidak boleh kosong!"})}async function preview(t){try{const a=await(await fetch(`/api/template?id=${t}`,{method:"GET"})).json();a.data&&addPreview(a.data)}catch(e){console.error("Gagal load preview:",e)}document.getElementById("templateModal").close()}function addPreview(t){document.getElementById("InputActivities").value=t.kegiatan||"",document.getElementById("InputVolume").value=t.volume||"",document.getElementById("Unit").value=t.satuan||"-",document.getElementById("InputCompletion").value=t.waktu||""}
